.rich audio, .editor-area audio { display: block; width: min(100%, 340px); height: 40px; margin: 8px auto; }
.occ-wrap { background: var(--surface-2); border: 1px dashed var(--border-strong); border-radius: var(--radius-sm); padding: 8px; display: grid; place-items: center; min-height: 120px; }
