@media (max-width: 960px) { .nav-btn.active { font-size: 0; gap: 0; padding: 10px 12px; } }

/* focus timer widget */
.focus-w { position: fixed; right: 16px; bottom: 16px; z-index: 60; width: 320px; max-width: calc(100vw - 24px); background: var(--surface); border: var(--border-w) solid var(--border-strong); border-radius: var(--radius); box-shadow: var(--shadow-lg); padding: 12px 14px; }
