.leo-bubble { position: absolute; z-index: 3; right: 216px; top: 68px; max-width: min(260px, 28%); padding: 9px 13px; border-radius: 14px 14px 4px 14px; background: rgba(255,255,255,.96); color: #1f2937; font-weight: 700; font-size: .9rem; line-height: 1.35; box-shadow: 0 10px 26px rgba(20,10,60,.3); animation: bubbleIn .25s cubic-bezier(.3,1.5,.5,1); transform-origin: right bottom; }
.leo-bubble::after { content: ""; position: absolute; right: -8px; bottom: 10px; border: 8px solid transparent; border-left-color: rgba(255,255,255,.96); border-right: 0; }
.leo-bubble.out { opacity: 0; transform: scale(.92); transition: .24s; }
@media (max-width: 767px) { .leo-bubble { display: none; } }
@media (prefers-reduced-motion: reduce) { .leo-bubble { animation: none; } }

/* ================= Léo, the clay lion: resting stills + transparent animated clips (see mascot.js) ================= */
.leo3d { position: relative; width: 100%; height: 100%; }
.leo-glow { position: absolute; left: 50%; top: 58%; width: 150%; aspect-ratio: 1; transform: translate(-50%, -50%); border-radius: 50%; z-index: 0; pointer-events: none; animation: leoGlow 4.2s ease-in-out infinite alternate;
  background: radial-gradient(closest-side, color-mix(in srgb, #ffc860 55%, var(--primary, #6366f1)) 0, color-mix(in srgb, #ffa530 20%, var(--primary, #6366f1)) 50%, transparent 74%); }
@keyframes leoGlow { from { opacity: .6; transform: translate(-50%, -50%) scale(.94); } to { opacity: .92; transform: translate(-50%, -50%) scale(1.05); } }
.leo-star { position: absolute; left: var(--x); top: var(--y); width: var(--s); height: var(--s); background: #fff1b8; clip-path: polygon(50% 0, 61% 39%, 100% 50%, 61% 61%, 50% 100%, 39% 61%, 0 50%, 39% 39%); opacity: 0; animation: leoTwinkle 3.4s ease-in-out infinite; animation-delay: var(--d); z-index: 0; pointer-events: none; }
@keyframes leoTwinkle { 0%, 100% { opacity: 0; transform: scale(.4) rotate(0); } 45% { opacity: .95; transform: scale(1) rotate(25deg); } 70% { opacity: .3; transform: scale(.7) rotate(40deg); } }
/* the figure sits on the floor of its slot; every layer shares the same box (the crop of the clips) */
.leo-pose { position: absolute; left: 0; bottom: 0; width: 100%; aspect-ratio: var(--ar, 1); z-index: 1; will-change: transform; transform: translateZ(0); }   /* his own layer: a new frame never repaints the card behind him */
.leo-off *, .leo-off { animation-play-state: paused !important; }
.leo-shadow { position: absolute; left: 50%; bottom: 1%; width: 46%; height: 6%; transform: translateX(-50%); border-radius: 50%; background: radial-gradient(closest-side, rgba(20, 8, 50, .45), transparent); z-index: 0; pointer-events: none; }
.leo-fig { position: absolute; inset: 0; }
.lf-still { position: absolute; inset: 0; }
.lf-still, .lf-clip { max-width: none; background-repeat: no-repeat; background-size: 100% 100%; pointer-events: none; user-select: none; -webkit-user-drag: none; }
.leo3d[data-state="s1"] .lf-still { background-image: var(--leo-s1); }
.leo3d[data-state="s0"] .lf-still { background-image: var(--leo-s0); }
.leo3d[data-state="sleep"] .lf-still { background-image: var(--leo-sleep); }
.leo3d[data-state="sleep"]:not(.leo-off) .lf-still { transform-origin: 50% 100%; animation: leoBreath 4.4s ease-in-out infinite; }   /* asleep, he breathes slowly */
@keyframes leoBreath { 50% { transform: scale(1.012, 1.024); } }
@media (prefers-reduced-motion: reduce) { .leo3d[data-state="sleep"] .lf-still { animation: none; } }
.lv-idle .lf-still, .lv-clip .lf-still { visibility: hidden; }
.lf-clip { position: absolute; opacity: 0; transition: opacity .14s linear; image-rendering: auto; }
.lf-clip.on { opacity: 1; }
.hero .mascot { animation: none; }
.lf-clip.flip { transform: scaleX(-1); }
.lf-idle { z-index: 1; opacity: 1; transition: none; }
.lf-play { z-index: 2; }
.leo-z { display: none; position: absolute; z-index: 2; font-weight: 900; color: #fff; text-shadow: 0 2px 6px rgba(0,0,0,.35); animation: leoZ 3s ease-in infinite; opacity: 0; }
.leo3d[data-state="sleep"] .leo-z { display: block; }
.leo-z.z1 { right: 12%; top: 18%; font-size: 1.2rem; } .leo-z.z2 { right: 2%; top: 4%; font-size: .9rem; animation-delay: 1.2s; }
@keyframes leoZ { 0% { opacity: 0; transform: translateY(8px) scale(.7); } 30% { opacity: 1; } 100% { opacity: 0; transform: translateY(-16px) scale(1.1); } }
/* golden ribbon of sparkles for milestones */
.leo-trail { position: absolute; left: 50%; top: 50%; width: 260%; aspect-ratio: 4 / 3; transform: translate(-50%, -50%); pointer-events: none; z-index: 3; overflow: visible; filter: drop-shadow(0 0 6px rgba(255, 200, 80, .8)); animation: trailFade 3.2s ease-out forwards; }
.leo-trail .tp { stroke-dasharray: 1; stroke-dashoffset: 1; animation: trailDraw 1.5s ease-out forwards; }
@keyframes trailDraw { to { stroke-dashoffset: 0; } }
.leo-trail .td { opacity: 0; animation: tdPop 1.4s ease-out forwards; }
@keyframes tdPop { 0% { opacity: 0; transform: scale(0); } 30% { opacity: 1; transform: scale(1.4); } 100% { opacity: .9; transform: scale(1); } }
@keyframes trailFade { 0%, 60% { opacity: 1; } 100% { opacity: 0; } }
.hero .mascot, .summary-mascot, .empty-mascot { overflow: visible; }
.hero .mascot::before { display: none; }
.summary-mascot { width: 220px; height: 220px; }
.empty-mascot { width: 160px; height: 160px; }
.hero { overflow-x: clip; overflow-y: visible; } body { overflow-x: clip; }
@media (prefers-reduced-motion: reduce) { .lf-clip { transition: none; } .leo-glow, .leo-star, .leo-z, .leo-trail, .leo-trail * { animation: none !important; } .leo-star { opacity: .6; } .leo-trail { display: none; } }

/* Léo in the smaller places: the library, empty lists, clean-up results */
.empty-mascot.sm { width: 120px; height: 120px; margin: 0 auto 8px; }
.empty .empty-mascot { position: relative; }
.lib-hello { display: flex; align-items: flex-end; gap: 12px; margin-bottom: 14px; }
.lib-mascot { position: relative; flex: 0 0 96px; width: 96px; height: 96px; }
.lib-hello p { flex: 1; }
.clean-hello { text-align: center; }
.lib-mascot .leo-glow, .lib-mascot .leo-star, .empty-mascot.sm .leo-glow, .empty-mascot.sm .leo-star { display: none; }
.lib-hello { align-items: center; }
.leo-fig.tap { animation: leoTapSquash .4s cubic-bezier(.3,1.5,.5,1); transform-origin: 50% 96%; }
@keyframes leoTapSquash { 0% { transform: scale(1); } 30% { transform: scale(1.05, .94); } 62% { transform: scale(.98, 1.04); } 100% { transform: scale(1); } }
@media (prefers-reduced-motion: reduce) { .leo-fig.tap { animation: none; } }

/* slow device: no entrance animations on the screens (everything else stays) */
[data-lite] .view-in, [data-lite] .view-in *, [data-lite] .cascade > *, [data-lite] .cascade .panel { animation: none !important; }
.backup-code code { display: inline-block; margin-top: 6px; padding: 6px 10px; border-radius: 8px; background: var(--surface); border: 1px solid var(--line, var(--border)); font: 700 .95rem/1.2 'JetBrains Mono', ui-monospace, monospace; letter-spacing: .04em; user-select: all; }

