[data-theme="savane"] {
  --font: 'Nunito', system-ui, sans-serif; --font-display: 'Playfair Display', Georgia, serif; --font-card: 'Nunito', system-ui, sans-serif;
  --bg: #f7e9cc;
  --bg-accent: radial-gradient(280px 34px at 16% 13%, rgba(255,255,255,.55), transparent 70%), radial-gradient(360px 40px at 60% 21%, rgba(255,255,255,.40), transparent 70%), radial-gradient(230px 30px at 92% 31%, rgba(255,255,255,.34), transparent 70%), radial-gradient(560px 460px at 84% 4%, rgba(255,205,110,.85), rgba(255,184,84,.28) 46%, transparent 72%), linear-gradient(180deg, #fbdfae 0%, #f8e8c8 34%, #f3deb4 100%);
  --surface: rgba(255,251,240,.54); --surface-solid: #fffaee; --surface-2: rgba(250,236,204,.55); --surface-3: rgba(240,220,176,.62);
