  --primary: #b45309; --primary-2: #d97706; --on-primary: #fff; --primary-soft: rgba(180,83,9,.12);
  --new: #1f66a8; --learn: #a16207; --due: #b91c1c; --mature: #4d7c0f;
  --again: #b91c1c; --hard: #a16207; --good: #1f66a8; --easy: #4d7c0f;
  --hero: linear-gradient(135deg, #8f2f0b 0%, #b45309 52%, #9a6205 100%); --on-hero: #fff8ec;
  --shadow: 0 6px 22px rgba(120,70,20,.13), inset 0 1px 0 rgba(255,255,255,.7); --shadow-lg: 0 16px 44px rgba(120,60,10,.22);
  --radius: 20px; --radius-sm: 14px;
