/* ---------- Savane étoilée : the savanna from sunset to night (same drawings as the Savane: acacia, hills, grass; a violet-to-gold sky, a low sun, a starry upper sky) ---------- */
[data-theme="savanenuit"] { color-scheme: dark; --theme-color: #1a1348; --heading-spacing: 0; }
[data-theme="savanenuit"] {
  --font: 'Nunito', system-ui, sans-serif; --font-display: 'Playfair Display', Georgia, serif; --font-card: 'Nunito', system-ui, sans-serif;
  --bg: linear-gradient(180deg, #15103f 0%, #2b2070 38%, #5a2b8a 64%, #96408f 80%, #e2605f 90%, #ff9f4a 96%, #ffd070 100%);
  --bg-accent: radial-gradient(900px 520px at 14% 70%, rgba(255,120,150,.14), transparent 62%), linear-gradient(112deg, transparent 36%, rgba(210,190,255,.06) 46%, rgba(255,220,200,.09) 52%, rgba(210,190,255,.05) 59%, transparent 68%);
  --surface: rgba(36,21,70,.8); --surface-solid: #26154a; --surface-2: rgba(56,34,100,.82); --surface-3: rgba(76,48,128,.86);
  --border: rgba(255,196,130,.24); --border-strong: rgba(255,196,130,.46);
  --text: #fff3e2; --text-muted: #e8d3c0; --text-faint: #bfa6a4;
  --primary: #ffb454; --primary-2: #ff8a5c; --on-primary: #2a1200; --primary-soft: rgba(255,180,84,.16);
  --new: #8fc1ff; --learn: #ffd466; --due: #ff9a8a; --mature: #8de6a6;
  --again: #ff9a8a; --hard: #ffd466; --good: #8fc1ff; --easy: #8de6a6;
  --hero: linear-gradient(180deg, #1b1450 0%, #3d2679 46%, #7a3a8f 100%); --on-hero: #fff7ea;   /* (the orange of the horizon is painted below, in the banner's picture) */
  --shadow: 0 0 0 1px rgba(255,196,130,.12), 0 8px 28px rgba(14,6,36,.45); --shadow-lg: 0 0 0 1px rgba(255,196,130,.22), 0 18px 48px rgba(14,6,36,.55);
  --radius: 20px; --radius-sm: 14px;
}
