@media (max-width: 767px) { [data-theme="savanenuit"] body::before { bottom: calc(66px + env(safe-area-inset-bottom, 0px)); height: 84px; background-size: 560px 86px, 560px 86px; } }
@media (max-width: 767px) { html[data-theme="savanenuit"]:has(body.in-session) body::before { bottom: 0; } }   /* (no bottom bar during a review) */
[data-theme="savanenuit"] body::after { top: 9vh; right: 14vw; width: 150px; height: 2px; background: linear-gradient(90deg, #fff, rgba(255,226,170,.5) 30%, transparent); border-radius: 2px; opacity: 0; transform: rotate(-34deg); animation: starShoot 23s linear 9s infinite; }
@media (max-width: 767px) { [data-theme="savanenuit"] body::after { display: none; } }
html[data-theme="savanenuit"]:has(body.in-session) body::after, html[data-theme="savanenuit"][data-lite] body::after { animation: none !important; }
@media (prefers-reduced-motion: reduce) { [data-theme="savanenuit"] body::after { display: none; } }
/* ===== animated themes (generated) ===== */

/* ---------- Fonds marins : under the sea (bubbles rise in the banner, a school of fish swims across now and then, the sea-weed at the bottom of the page sways on a computer) ---------- */
[data-theme="abysses"] { color-scheme: dark; --theme-color: #0a5775; --heading-spacing: 0; }
[data-theme="abysses"] {
  --font: 'Nunito', system-ui, sans-serif; --font-display: 'Nunito', system-ui, sans-serif; --font-card: 'Nunito', system-ui, sans-serif;
  --bg: linear-gradient(180deg, #0d6f86 0%, #0a4b79 30%, #072d5a 62%, #041835 100%);
  --bg-accent: radial-gradient(900px 480px at 20% 0%, rgba(160,240,255,.20), transparent 62%), linear-gradient(105deg, transparent 20%, rgba(200,250,255,.05) 34%, transparent 46%), linear-gradient(105deg, transparent 52%, rgba(200,250,255,.04) 62%, transparent 72%);
  --surface: rgba(5,38,74,.78); --surface-solid: #072a52; --surface-2: rgba(10,58,104,.8); --surface-3: rgba(16,82,134,.84);
  --border: rgba(150,235,255,.2); --border-strong: rgba(150,235,255,.42);
  --text: #e9fbff; --text-muted: #b3dcea; --text-faint: #7fb0c4;
  --primary: #2dd4bf; --primary-2: #ff8a7a; --on-primary: #012a28; --primary-soft: rgba(45,212,191,.16);
  --new: #7fd6ff; --learn: #ffd56b; --due: #ff9c8a; --mature: #69e3b0;
  --again: #ff9c8a; --hard: #ffd56b; --good: #7fd6ff; --easy: #69e3b0;
  --hero: linear-gradient(180deg, #0f7f94 0%, #0b5a88 46%, #082f66 100%); --on-hero: #effcff;
  --shadow: 0 0 0 1px rgba(150,235,255,.1), 0 8px 28px rgba(0,16,40,.45); --shadow-lg: 0 0 0 1px rgba(150,235,255,.2), 0 18px 48px rgba(0,16,40,.55);
  --radius: 22px; --radius-sm: 15px;
}
[data-theme="abysses"] .hero { background: url("data:image/webp;base64,") no-repeat 100% 100% / auto 100%, var(--hero); border: 1px solid rgba(150,235,255,.34); }
@media (max-width: 767px) { [data-theme="abysses"] .hero { background-size: auto 100%, auto; } }
[data-theme="abysses"] .hero-title { text-shadow: 0 2px 14px rgba(0,30,60,.5); }
[data-theme="abysses"] .btn-primary { background: linear-gradient(135deg, #2dd4bf, #38bdf8); color: #012a28; }
[data-theme="abysses"] .btn-hero { background: rgba(239,252,255,.95); color: #06385a; }
[data-theme="abysses"] .logo-mark { box-shadow: 0 0 16px rgba(45,212,191,.45); }
[data-theme="abysses"] .topbar { background: linear-gradient(180deg, rgba(8,92,118,.96), rgba(8,70,110,.9)); border-bottom-color: rgba(150,235,255,.26); }
[data-theme="abysses"] .bottom-nav { background: linear-gradient(0deg, rgba(4,24,53,.97), rgba(7,45,90,.92)); border-top-color: rgba(150,235,255,.26); }
[data-theme="abysses"] .leo-glow { filter: opacity(.4) hue-rotate(120deg); }
[data-theme="abysses"] .study-actions { background: none; }
