/* ---------- Hiver : a snowy evening (big flakes fall in the banner, pines, a lit cabin, the mountains behind) ---------- */
[data-theme="hiver"] { --theme-color: #cfd3ee; --heading-spacing: 0; }
[data-theme="hiver"] {
  --font: 'Nunito', system-ui, sans-serif; --font-display: 'Nunito', system-ui, sans-serif; --font-card: 'Nunito', system-ui, sans-serif;
  --bg: linear-gradient(180deg, #b4bce2 0%, #cdd2ee 30%, #e3e3f4 62%, #f2f1fa 100%);
  --bg-accent: radial-gradient(900px 440px at 84% 0%, rgba(255,196,196,.42), transparent 62%), radial-gradient(800px 400px at 0% 22%, rgba(255,255,255,.5), transparent 62%);
  --surface: rgba(252,250,255,.86); --surface-solid: #fcfaff; --surface-2: rgba(238,236,250,.9); --surface-3: rgba(220,218,242,.93);
  --border: rgba(130,128,196,.30); --border-strong: rgba(98,100,176,.50);
  --text: #16294a; --text-muted: #4a5584; --text-faint: #7b84ae;
  --primary: #2563c9; --primary-2: #e8604c; --on-primary: #ffffff; --primary-soft: rgba(37,99,201,.12);
  --new: #2563c9; --learn: #b7791f; --due: #c43d3d; --mature: #2f855a;
  --again: #c43d3d; --hard: #b7791f; --good: #2563c9; --easy: #2f855a;
  --hero: linear-gradient(180deg, #1b3560 0%, #2c4e86 52%, #43699f 100%); --on-hero: #f4f9ff;
  --shadow: 0 6px 22px rgba(60,60,130,.14), inset 0 1px 0 rgba(255,255,255,.8); --shadow-lg: 0 16px 44px rgba(50,50,120,.26);
  --radius: 22px; --radius-sm: 15px;
}
[data-theme="hiver"] .hero { background: url("data:image/webp;base64,") no-repeat 100% 100% / auto 100%, var(--hero); }
@media (max-width: 767px) { [data-theme="hiver"] .hero { background-size: auto 100%, auto; } }
[data-theme="hiver"] .btn-primary { background: linear-gradient(135deg, #2f74e0, #1f55b4); }
[data-theme="hiver"] .btn-hero { background: rgba(255,255,255,.95); color: #16294a; }
[data-theme="hiver"] .btn-hero-ghost { background: rgba(18,40,82,.62); color: #fff; border-color: rgba(255,255,255,.55); }
[data-theme="hiver"] .logo-mark { box-shadow: 0 4px 14px rgba(37,99,201,.3); }
[data-theme="hiver"] .topbar { background: linear-gradient(180deg, rgba(176,184,226,.96), rgba(204,208,238,.9)); border-bottom-color: rgba(120,120,190,.42); }
[data-theme="hiver"] .bottom-nav { background: linear-gradient(0deg, rgba(222,222,244,.97), rgba(238,236,250,.93)); border-top-color: rgba(120,120,190,.42); }
[data-theme="hiver"] .leo-glow { filter: opacity(.5) hue-rotate(190deg); }
