[data-theme="sakura"] body[data-view="toeic"] { --hs-img: var(--pg-torii); --hs-ar: calc(100vw * .3167); }
[data-theme="sakura"] body[data-view="settings"] { --hs-img: var(--pg-village); --hs-ar: calc(100vw * .3167); }
[data-theme="sakura"] body::before { content: ""; position: fixed; z-index: -1; pointer-events: none; left: 0; right: 0; bottom: 0; height: max(var(--hs-h), var(--hs-ar)); background: var(--im-tree) no-repeat right bottom / cover, var(--im-scene) no-repeat right bottom / cover; opacity: .9; }
[data-theme="sakura"] body[data-view="decks"]::before, [data-theme="sakura"] body[data-view="stats"]::before, [data-theme="sakura"] body[data-view="toeic"]::before, [data-theme="sakura"] body[data-view="settings"]::before { background: var(--hs-img) no-repeat center bottom / cover; }
@media (max-width: 767px) { [data-theme="sakura"] { --hs-h: 30vh; } [data-theme="sakura"] body::before { bottom: calc(66px + env(safe-area-inset-bottom, 0px)); background-position: 78% bottom, 78% bottom; } [data-theme="sakura"] body[data-view="decks"]::before, [data-theme="sakura"] body[data-view="stats"]::before, [data-theme="sakura"] body[data-view="toeic"]::before, [data-theme="sakura"] body[data-view="settings"]::before { background-position: center bottom; } html[data-theme="sakura"]:has(body.in-session) body::before { bottom: 0; } }
/* readable titles over the scene, soft white cards */
[data-theme="sakura"] .section-head, [data-theme="sakura"] .view h1, [data-theme="sakura"] .page-title { text-shadow: 0 0 10px rgba(255,244,248,.95), 0 0 3px rgba(255,255,255,.9); }
[data-theme="sakura"] .panel { background: linear-gradient(180deg, rgba(255,255,255,.96), rgba(255,243,248,.9)); border-color: rgba(255,255,255,.95); box-shadow: 0 6px 22px rgba(219,39,119,.12), inset 0 0 0 1px rgba(236,150,185,.28), inset 0 1px 0 #fff; }

/* ===== end animated themes ===== */
/* quiet while reviewing, and wherever motion is not wanted or the device is slow */
html[data-theme="etoile"]:has(body.in-session)::before, html[data-theme="etoile"]:has(body.in-session)::after, html[data-theme="etoile"]:has(body.in-session) body::after,
html[data-theme="savane"]:has(body.in-session)::before, html[data-theme="savane"]:has(body.in-session) body::before, html[data-theme="savane"]:has(body.in-session) body::after { animation: none; }
html[data-theme="etoile"][data-lite]::before, html[data-theme="etoile"][data-lite]::after, html[data-theme="etoile"][data-lite] body::after,
html[data-theme="savane"][data-lite]::before, html[data-theme="savane"][data-lite] .hero::before, html[data-theme="savane"][data-lite] body::before, html[data-theme="savane"][data-lite] body::after { animation: none !important; }
@media (prefers-reduced-motion: reduce) {
  html[data-theme="etoile"]::before, html[data-theme="etoile"]::after, [data-theme="etoile"] body::after, html[data-theme="savane"]::before, [data-theme="savane"] body::before, [data-theme="savane"] body::after, [data-theme="savane"] .hero::before { animation: none !important; }
  [data-theme="etoile"] body::after { display: none; }
}
.ex-m.ok { color: var(--mature); } .ex-m.mid { color: var(--learn); } .ex-m.low { color: var(--due); }
.ex-done { display: inline-flex; align-items: center; gap: 6px; font-size: .86rem; font-weight: 700; color: var(--mature); }

.menu-size { display: flex; align-items: center; justify-content: space-between; gap: 14px; padding: 8px 12px; font-weight: 600; font-size: .92rem; }
.menu-size .ms-btns { display: inline-flex; gap: 6px; }
.menu-size button { min-width: 44px; padding: 7px 10px; border-radius: 10px; border: 1px solid var(--border-strong); background: var(--surface-2); color: var(--text); font-weight: 800; cursor: pointer; }
.menu-size button:hover { background: var(--primary-soft); }

/* swipes: the review card shows what the answer will be, a list row shows what the swipe will do */
.flashcard.swipe-easy { box-shadow: 0 0 0 3px var(--easy, #4d7c0f), var(--shadow-lg); }
.flashcard.swipe-hard { box-shadow: 0 0 0 3px var(--hard, #a16207), var(--shadow-lg); }
.flashcard[data-swipe]::after { content: attr(data-swipe); position: absolute; top: 12px; left: 50%; transform: translateX(-50%); padding: 5px 14px; border-radius: 999px; background: var(--surface-solid, #fff); color: var(--text); font-weight: 800; font-size: .9rem; box-shadow: 0 4px 14px rgba(0,0,0,.18); pointer-events: none; }
.card-row { position: relative; touch-action: pan-y; }
.card-row .row-actions { position: absolute; left: 100%; top: 0; bottom: 0; width: 168px; display: flex; align-items: center; justify-content: center; gap: 8px; padding-left: 8px; }
.row-actions button { display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 2px; width: 74px; height: 56px; border: 0; border-radius: 20px; color: #fff; font: inherit; cursor: pointer; }
.row-actions button:first-child { background: #d97706; } .row-actions button:last-child { background: #6366f1; }
.row-actions .i { width: 20px; height: 20px; } .row-actions small { font-size: .66rem; font-weight: 800; }
.card-row.sw-r::after { content: "⭐ Marquer"; left: 14px; right: auto; margin-left: -118px; }
.card-row.sw-l::after { content: "Enfouir 🙈"; right: 14px; margin-right: -118px; }
.flashcard.swiping::before { content: ""; position: absolute; inset: 0; border-radius: inherit; background: var(--sw-c); opacity: var(--sw-a, 0); pointer-events: none; z-index: 3; }

.tally { display: flex; justify-content: center; flex-wrap: wrap; gap: 6px 12px; margin: 8px 0 2px; font-size: .78rem; font-weight: 700; color: var(--text-muted); }
.tally span { display: inline-flex; align-items: center; gap: 5px; white-space: nowrap; }
.tally i { width: 8px; height: 8px; border-radius: 50%; background: var(--c); }
.tally b { color: var(--text); font-variant-numeric: tabular-nums; }
body.zen .tally { display: none; }

html { overscroll-behavior-x: none; }   /* (a sideways slide on a trackpad changes the tab of the app, it does not go back in the browser) */
body.dragging, body.dragging * { user-select: none !important; cursor: grabbing !important; }
.flashcard.swiping { cursor: grabbing; }
